class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        TreeSet<Integer> endpoints = new TreeSet<>();
        for (int[] square : positions) {
            endpoints.add(square[0]);
            endpoints.add(square[0] + square[1]);
        }

        Map<Integer, Integer> index = new HashMap<>();
        int id = 0;
        for (int x : endpoints) {
            index.put(x, id++);
        }

        int[] blockHeights = new int[Math.max(1, id - 1)];
        List<Integer> answer = new ArrayList<>();
        int highest = 0;
        for (int[] square : positions) {
            int left = index.get(square[0]);
            int right = index.get(square[0] + square[1]);
            int base = 0;
            for (int i = left; i < right; i++) {
                base = Math.max(base, blockHeights[i]);
            }
            int newHeight = base + square[1];
            for (int i = left; i < right; i++) {
                blockHeights[i] = newHeight;
            }
            highest = Math.max(highest, newHeight);
            answer.add(highest);
        }
        return answer;
    }
}

import java.util.*;

class Solution {
    private int[] tree;
    private int[] lazy;

    public List<Integer> fallingSquares(int[][] positions) {
        Set<Integer> coords = new TreeSet<>();
        for (int[] p : positions) {
            coords.add(p[0]);
            coords.add(p[0] + p[1] - 1);
            coords.add(p[0] + p[1]);
        }
        Map<Integer, Integer> compress = new HashMap<>();
        int idx = 0;
        for (int c : coords) compress.put(c, idx++);
        int sz = idx;
        tree = new int[4 * sz];
        lazy = new int[4 * sz];
        List<Integer> result = new ArrayList<>();
        int maxH = 0;
        for (int[] p : positions) {
            int left = compress.get(p[0]);
            int right = compress.get(p[0] + p[1] - 1);
            int curMax = query(1, 0, sz - 1, left, right);
            int newH = curMax + p[1];
            update(1, 0, sz - 1, left, right, newH);
            maxH = Math.max(maxH, newH);
            result.add(maxH);
        }
        return result;
    }
    private void pushDown(int node) {
        if (lazy[node] > 0) {
            tree[2 * node] = Math.max(tree[2 * node], lazy[node]);
            tree[2 * node + 1] = Math.max(tree[2 * node + 1], lazy[node]);
            lazy[2 * node] = Math.max(lazy[2 * node], lazy[node]);
            lazy[2 * node + 1] = Math.max(lazy[2 * node + 1], lazy[node]);
            lazy[node] = 0;
        }
    }
    private int query(int node, int lo, int hi, int l, int r) {
        if (l > hi || r < lo) return 0;
        if (l <= lo && hi <= r) return tree[node];
        pushDown(node);
        int mid = (lo + hi) / 2;
        return Math.max(query(2 * node, lo, mid, l, r), query(2 * node + 1, mid + 1, hi, l, r));
    }
    private void update(int node, int lo, int hi, int l, int r, int val) {
        if (l > hi || r < lo) return;
        if (l <= lo && hi <= r) {
            tree[node] = Math.max(tree[node], val);
            lazy[node] = Math.max(lazy[node], val);
            return;
        }
        pushDown(node);
        int mid = (lo + hi) / 2;
        update(2 * node, lo, mid, l, r, val);
        update(2 * node + 1, mid + 1, hi, l, r, val);
        tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
    }
}

import java.util.*;

class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        TreeMap<Integer, int[]> intervals = new TreeMap<>();
        List<Integer> answer = new ArrayList<>();
        int highest = 0;

        for (int[] position : positions) {
            int left = position[0];
            int right = left + position[1];
            split(intervals, left);
            split(intervals, right);

            int base = 0;
            for (Map.Entry<Integer, int[]> entry = intervals.ceilingEntry(left);
                 entry != null && entry.getKey() < right;
                 entry = intervals.higherEntry(entry.getKey())) {
                base = Math.max(base, entry.getValue()[1]);
            }

            List<Integer> toRemove = new ArrayList<>();
            for (Map.Entry<Integer, int[]> entry = intervals.ceilingEntry(left);
                 entry != null && entry.getKey() < right;
                 entry = intervals.higherEntry(entry.getKey())) {
                toRemove.add(entry.getKey());
            }
            for (int key : toRemove) {
                intervals.remove(key);
            }

            int height = base + position[1];
            intervals.put(left, new int[]{right, height});
            highest = Math.max(highest, height);
            answer.add(highest);
        }

        return answer;
    }

    private void split(TreeMap<Integer, int[]> intervals, int x) {
        Map.Entry<Integer, int[]> floor = intervals.floorEntry(x);
        if (floor == null) {
            return;
        }
        int start = floor.getKey();
        int[] segment = floor.getValue();
        if (start < x && x < segment[0]) {
            int oldEnd = segment[0];
            int height = segment[1];
            segment[0] = x;
            intervals.put(x, new int[]{oldEnd, height});
        }
    }
}

import java.util.*;

class Solution {
    private static final int LIMIT = 1_100_000_000;

    public List<Integer> fallingSquares(int[][] positions) {
        Node root = new Node();
        List<Integer> answer = new ArrayList<>();
        int highest = 0;

        for (int[] square : positions) {
            int left = square[0];
            int right = left + square[1] - 1;
            int base = query(root, 1, LIMIT, left, right);
            int newHeight = base + square[1];
            update(root, 1, LIMIT, left, right, newHeight);
            highest = Math.max(highest, newHeight);
            answer.add(highest);
        }

        return answer;
    }

    private int query(Node node, int lo, int hi, int left, int right) {
        if (node == null || right < lo || hi < left) {
            return 0;
        }
        if (left <= lo && hi <= right) {
            return node.max;
        }
        push(node);
        int mid = lo + (hi - lo) / 2;
        return Math.max(query(node.left, lo, mid, left, right),
                query(node.right, mid + 1, hi, left, right));
    }

    private void update(Node node, int lo, int hi, int left, int right, int value) {
        if (right < lo || hi < left) {
            return;
        }
        if (left <= lo && hi <= right) {
            node.max = value;
            node.lazy = value;
            return;
        }
        push(node);
        int mid = lo + (hi - lo) / 2;
        update(node.left, lo, mid, left, right, value);
        update(node.right, mid + 1, hi, left, right, value);
        node.max = Math.max(node.left.max, node.right.max);
    }

    private void push(Node node) {
        if (node.left == null) {
            node.left = new Node();
        }
        if (node.right == null) {
            node.right = new Node();
        }
        if (node.lazy != 0) {
            node.left.max = node.lazy;
            node.right.max = node.lazy;
            node.left.lazy = node.lazy;
            node.right.lazy = node.lazy;
            node.lazy = 0;
        }
    }

    private static final class Node {
        private Node left;
        private Node right;
        private int max;
        private int lazy;
    }
}
